create database galeria;
use galeria;
create table persona ( id int primary key auto_increment not null, nombre varchar(30), segundoNombre varchar(30), apellido varchar(30), segundoApellido varchar(30), documento varchar(12), nacimiento date, sexo enum ('f','m'), email varchar(30));
create table telefono ( id int primary key auto_increment not null, persona int, pais int, cArea int, numero int, foreign key (persona) references persona(id));
create table direccion ( id int primary key auto_increment not null, persona int, calle varchar(30), numero int, manzana varchar(10), lote varchar(10), edificio varchar(10), piso int, departamento varchar(10), barrio varchar(30), localidad varchar(30), ciudad varchar(30), provincia varchar(30), pais varchar(30), codigoPostal varchar(10),foreign key (persona) references persona(id));
create table rubro ( id int primary key auto_increment not null, rubro varchar(30), descripcion varchar(100));
create table inquilino (id int primary key auto_increment not null, persona int, alta date, foreign key(persona) references persona(id));
create table espacio (id int primary key auto_increment not null, nombre varchar(30), estado enum('libre','ocupado','revervado','mantenimiento'), ancho int, largo int, tipo varchar(30), inquilino int, precio decimal(8,2), rubro int, recargoUbicaion decimal(3,2), descripcion varchar(100), foreign key(inquilino) references inquilino(id), foreign key(rubro) references rubro(id));
create table documentacion (id int primary key auto_increment not null, documento varchar(20), inquilino int, descripcion varchar(100), emision date, vencimiento date, fechaPresentacion date, foreign key(inquilino) references inquilino(id));
create table archivo (id int primary key auto_increment not null, documentacion int, archivo varchar(20), url varchar(15), foreign key(documentacion) references documentacion(id));
create table contrato (id int primary key auto_increment not null, registro datetime, fecha datetime, condiciones varchar(10000), inquilino int, espacio int, inicio datetime, fin datetime, nota varchar(400), foreign key(inquilino) references inquilino(id), foreign key(espacio) references espacio(id));
create table factura (id int primary key auto_increment not null, registro datetime, fecha datetime, numero int, estado enum('emitida','pagada'), inquilino int, nota varchar (400), foreign key(inquilino) references inquilino(id));
create table servicio (id int primary key auto_increment not null, servicio varchar(30), cantidad int, precio decimal(10,2), factura int, nota varchar(400), foreign key(factura) references factura(id));
create table rol ( id int primary key auto_increment not null, rol varchar(30), descripcion varchar(400), nota varchar(400));
create table usuario (id int primary key auto_increment, usuario varchar(30), clave varchar(30), persona int, rol int, estado enum('activo','inactivo'), creacion date, ultimoAcceso date, foreign key(persona) references persona(id), foreign key(rol) references rol(id));
create table pago (id int primary key auto_increment not null, registro datetime, fecha datetime, usuario int, factura int, item varchar(30), inquilino int, nota varchar(400), foreign key(usuario) references usuario(id), foreign key(factura) references factura(id), foreign key(inquilino) references inquilino(id));
create table alquiler ( id int primary key auto_increment not null, contrato int, espacio int, inicio datetime, fin datetime, estado enum('activo','inactivo'), nota varchar(400), foreign key(contrato) references contrato(id), foreign key(espacio) references espacio(id));
create table reserva (id int primary key auto_increment not null, fecha date, espacio int, inquilino int, tipo varchar(30), diaInicio date, diaFin date, inicio time, fin time, actividad varchar(30), adelanto decimal(10,2), estado enum('pagado','adeudado'), nota varchar(400), foreign key(espacio) references espacio(id), foreign key(inquilino) references inquilino(id));